input.sparql:
SELECT ?zoneName ?zone ?point ?pointClass ?seriesId WHERE {
  ?zone a brick:Zone ; rdfs:label ?zoneName .
  OPTIONAL { ?point brick:hasSubComponent ?zone . }
  OPTIONAL { ?zone brick:hasSubComponent ?point . }
  OPTIONAL { ?point ref:hasTimeseriesId ?seriesId . }
  OPTIONAL { ?point a brick:hasType . }
}

