import csv, datetime
from collections import defaultdict
z = {
 'sensor':'baef86cb-2941-5d61-87b0-ffa91d79f23a',
 'setpoint_cmd':'1213f3a8-c23d-55b5-8187-4712d49a82ae',
 'sched_sp':'c5120bcb-e5c2-5714-a171-cbdb1f8ef5ab',
}
target = set(z.values())
rev = {v:k for k,v in z.items()}
data = {k:{} for k in z}
with open(VALUES_CSV) as f:
    rd=csv.reader(f); next(rd)
    for row in rd:
        if row[0] in target:
            data[rev[row[0]]][row[1]] = float(row[2])

allts = sorted(data['sensor'])
def dt(s): return datetime.datetime.strptime(s,"%Y-%m-%dT%H:%M:%S")
def hour(s): return dt(s).hour
def avg(key, ts):
    vals=[data[key][t] for t in ts if t in data[key]]
    return sum(vals)/len(vals) if vals else None

for label, period in [("before_mid_june", lambda d: d.year==2018 and (d.month<6 or (d.month==6 and d.day<15))),
                      ("after_mid_june",  lambda d: d.year==2018 and (d.month>6 or (d.month==6 and d.day>=15)))]:
    ts=[t for t in allts if period(dt(t))]
    occ=[t for t in ts if 7 <= hour(t) <= 18]
    print(label, "n_occ:", len(occ),
          "sensor:%.2f"%avg('sensor',occ),
          "setpoint_cmd:%.2f"%avg('setpoint_cmd',occ),
          "sched_sp:%.2f"%avg('sched_sp',occ))
